this.ws = new WebSocket(`${WS_URL}?token=${accessToken}`)

// 메시지 파싱 방어
this.ws.onmessage = (event) =&gt; {
  try {
    const data = JSON.parse(event.data);
    this.notifyListeners(data);
  } catch(e) {
