4. 이벤트 재생
🔄 Aggregate 복원
@Aggregate
public class OrderAggregate {

    @AggregateIdentifier
    private String orderId;
    private OrderStatus status;
    private List&lt;OrderItem&gt; items;
    private BigDecimal totalAmount;

    // 이벤트 재생으로 상태 복원
    public static OrderAggregate from(List&lt;DomainEvent&gt; events) {
        OrderAggregate order = new OrderAggregate();

        for (DomainEvent event : events) {
            order.apply(event);
        }

        return order;
    }

    private void apply(DomainEvent event) {
        if (event instanceof OrderCreatedEvent) {
            apply((OrderCreatedEvent) event);
        } else if (event instanceof OrderPaidEvent) {
            apply((OrderPaidEvent) event);
        } else if (event instanceof OrderCancelledEvent) {
            apply((OrderCancelledEvent) event);
        }
    }

    @EventSourcingHandler
    private void apply(OrderCreatedEvent event) {
        this.orderId = event.getOrderId();
        this.items = event.getItems();
        this.totalAmount = event.getTotalAmount();
        this.status = OrderStatus.CREATED;
    }

    @EventSourcingHandler
    private void apply(OrderPaidEvent event) {
        this.status = OrderStatus.PAID;
    }

    @EventSourcingHandler
    private void apply(OrderCancelledEvent event) {
        this.status = OrderStatus.CANCELLED;
    }
}

5. 실제 구현
💻 Axon Framework
// Command
public class CreateOrderCommand {
    @TargetAggregateIdentifier
    private final String orderId;
    private final String customerId;
    private final List&lt;OrderItem&gt; items;
}

// Event
public class OrderCreatedEvent {
    private final String orderId;
    private final String customerId;
    private final List&lt;OrderItem&gt; items;
    private final Instant createdAt;
}

// Aggregate
@Aggregate
public class OrderAggregate {

    @AggregateIdentifier
    private String orderId;
    private OrderStatus status;

    protected OrderAggregate() {
        // Axon requires no-arg constructor
    }

    @CommandHandler
    public OrderAggregate(CreateOrderCommand command) {
        // Validation
        validateCommand(command);

        // Publish event (Event Store에 저장)
        apply(new OrderCreatedEvent(
            command.getOrderId(),
            command.getCustomerId(),
            command.getItems(),
            Instant.now()
        ));
    }

    @EventSourcingHandler
    public void on(OrderCreatedEvent event) {
        // 상태 변경 (이벤트 재생 시 실행됨)
        this.orderId = event.getOrderId();
        this.status = OrderStatus.CREATED;
    }

    @CommandHandler
    public void handle(CancelOrderCommand command) {
        if (this.status == OrderStatus.SHIPPED) {
            throw new IllegalStateException(&quot;Cannot cancel shipped order&quot;);
        }

        apply(new OrderCancelledEvent(
            command.getOrderId(),
            command.getReason(),
            Instant.now()
        ));
    }

    @EventSourcingHandler
    public void on(OrderCancelledEvent event) {
        this.status = OrderStatus.CANCELLED;
    }
}

