// 📊 Redis 기반 분산 락
class RedisDistributedLock {
  private lockScript = `
    if redis.call(&quot;get&quot;, KEYS[1]) == ARGV[1] then
      return redis.call(&quot;del&quot;, KEYS[1])
    else
      return 0
    end
  `;

  constructor(private redis: Redis) {}

  async acquireLock(
    lockKey: string, 
    lockValue: string, 
    ttlSeconds: number = 30
  ): Promise&lt;boolean&gt; {
    const result = await this.redis.set(
      lockKey, 
      lockValue, 
      &#039;NX&#039;, 
      &#039;EX&#039;, 
      ttlSeconds
    );
    return result === &#039;OK&#039;;
  }

  async releaseLock(lockKey: string, lockValue: string): Promise&lt;boolean&gt; {
    const result = await this.redis.eval(
      this.lockScript,
      1,
      lockKey,
      lockValue
    );
    return result === 1;
  }

  async withLock&lt;T&gt;(
    lockKey: string,
    operation: () =&gt; Promise&lt;T&gt;,
    ttlSeconds: number = 30
  ): Promise&lt;T&gt; {
    const lockValue = generateUniqueId();
    const acquired = await this.acquireLock(lockKey, lockValue, ttlSeconds);

    if (!acquired) {
      throw new Error(`Could not acquire lock: ${lockKey}`);
    }

    try {
      // 자동 갱신을 위한 하트비트
      const heartbeat = this.startHeartbeat(lockKey, lockValue, ttlSeconds);
      const result = await operation();
      clearInterval(heartbeat);
      return result;
    } finally {
      await this.releaseLock(lockKey, lockValue);
    }
  }

  private startHeartbeat(
    lockKey: string, 
    lockValue: string, 
    ttlSeconds: number
  ): NodeJS.Timeout {
    return setInterval(async () =&gt; {
      try {
        await this.redis.expire(lockKey, ttlSeconds);
      } catch (error) {
        console.error(&#039;Lock heartbeat error:&#039;, error);
      }
    }, (ttlSeconds * 1000) / 3); // TTL의 1/3마다 갱신
  }
}
