🤔 질문: “매번 긴 명령어를 치기 번거로운데, 스크립트로 자동화할 수 없을까?”
📋 메인 배포 스크립트
#!/bin/bash
# 📊 deploy-to-cloudrun.sh - 범용 Cloud Run 배포 스크립트

set -e  # 오류 발생시 스크립트 중단

# 색상 출력 함수
RED=&#039;\033[0;31m&#039;
GREEN=&#039;\033[0;32m&#039;
YELLOW=&#039;\033[1;33m&#039;
BLUE=&#039;\033[0;34m&#039;
NC=&#039;\033[0m&#039; # No Color

log_info() { echo -e &quot;${BLUE}[INFO]${NC} $1&quot;; }
log_success() { echo -e &quot;${GREEN}[SUCCESS]${NC} $1&quot;; }
log_warning() { echo -e &quot;${YELLOW}[WARNING]${NC} $1&quot;; }
log_error() { echo -e &quot;${RED}[ERROR]${NC} $1&quot;; }

# 환경 변수 로드
if [[ -f ~/.cloudrun_env ]]; then
    source ~/.cloudrun_env
    log_info &quot;Environment variables loaded&quot;
else
    log_error &quot;Environment file not found. Run setup first.&quot;
    exit 1
fi

# 파라미터 파싱
SERVICE_NAME=&quot;&quot;
IMAGE_TAG=&quot;latest&quot;
MEMORY=&quot;512Mi&quot;
CPU=&quot;1&quot;
CONCURRENCY=&quot;80&quot;
MAX_INSTANCES=&quot;100&quot;
MIN_INSTANCES=&quot;0&quot;
TIMEOUT=&quot;300&quot;
ENV_VARS=&quot;&quot;
ALLOW_UNAUTHENTICATED=&quot;true&quot;

show_help() {
    cat &lt;&lt; EOF
Cloud Run 배포 스크립트

사용법: $0 [옵션]

필수 파라미터:
  -n, --name SERVICE_NAME        서비스 이름

선택적 파라미터:
  -t, --tag TAG                  이미지 태그 (기본값: latest)
  -m, --memory MEMORY           메모리 할당 (기본값: 512Mi)
  -c, --cpu CPU                 CPU 할당 (기본값: 1)
  --concurrency NUM             동시 요청 수 (기본값: 80)
  --max-instances NUM           최대 인스턴스 (기본값: 100)
  --min-instances NUM           최소 인스턴스 (기본값: 0)
  --timeout SECONDS             타임아웃 (기본값: 300)
  --env-vars &quot;KEY1=VALUE1,KEY2=VALUE2&quot;  환경 변수
  --no-allow-unauthenticated    인증 필요 설정
  -h, --help                    도움말 표시

예시:
  $0 -n my-app -t v1.0.0 -m 1Gi --env-vars &quot;NODE_ENV=production,DEBUG=false&quot;
EOF
}

# 파라미터 파싱
while [[ $#--gt-0-| -gt 0 ]]; do
    case $1 in
        -n|--name)
            SERVICE_NAME=&quot;$2&quot;
            shift 2
            ;;
        -t|--tag)
            IMAGE_TAG=&quot;$2&quot;
            shift 2
            ;;
        -m|--memory)
            MEMORY=&quot;$2&quot;
            shift 2
            ;;
        -c|--cpu)
            CPU=&quot;$2&quot;
            shift 2
            ;;
        --concurrency)
            CONCURRENCY=&quot;$2&quot;
            shift 2
            ;;
        --max-instances)
            MAX_INSTANCES=&quot;$2&quot;
            shift 2
            ;;
        --min-instances)
            MIN_INSTANCES=&quot;$2&quot;
            shift 2
            ;;
        --timeout)
            TIMEOUT=&quot;$2&quot;
            shift 2
            ;;
        --env-vars)
            ENV_VARS=&quot;$2&quot;
            shift 2
            ;;
        --no-allow-unauthenticated)
            ALLOW_UNAUTHENTICATED=&quot;false&quot;
            shift
            ;;
        -h|--help)
            show_help
            exit 0
            ;;
        *)
            log_error &quot;Unknown option $1&quot;
            show_help
            exit 1
            ;;
    esac
done

# 필수 파라미터 검증
if [[ -z &quot;$SERVICE_NAME&quot; ]]; then
    log_error &quot;Service name is required&quot;
    show_help
    exit 1
fi

# 이미지 이름 구성
IMAGE_NAME=&quot;gcr.io/$PROJECT_ID/$SERVICE_NAME:$IMAGE_TAG&quot;

log_info &quot;Starting deployment...&quot;
log_info &quot;Service: $SERVICE_NAME&quot;
log_info &quot;Image: $IMAGE_NAME&quot;
log_info &quot;Region: $REGION&quot;

# 1. Dockerfile 존재 확인
if [[ ! -f &quot;Dockerfile&quot; ]]; then
    log_error &quot;Dockerfile not found in current directory&quot;
    exit 1
fi

# 2. Docker 이미지 빌드
log_info &quot;Building Docker image...&quot;
docker build -t &quot;$IMAGE_NAME&quot; .
log_success &quot;Docker image built successfully&quot;

# 3. 이미지 푸시
log_info &quot;Pushing image to Container Registry...&quot;
docker push &quot;$IMAGE_NAME&quot;
log_success &quot;Image pushed successfully&quot;

# 4. Cloud Run 배포 명령어 구성
DEPLOY_CMD=&quot;gcloud run deploy $SERVICE_NAME \
  --image $IMAGE_NAME \
  --platform managed \
  --region $REGION \
  --memory $MEMORY \
  --cpu $CPU \
  --concurrency $CONCURRENCY \
  --max-instances $MAX_INSTANCES \
  --min-instances $MIN_INSTANCES \
  --timeout $TIMEOUT&quot;

# 환경 변수 추가
if [[ -n &quot;$ENV_VARS&quot; ]]; then
    DEPLOY_CMD=&quot;$DEPLOY_CMD --set-env-vars $ENV_VARS&quot;
fi

# 인증 설정
if [[ &quot;$ALLOW_UNAUTHENTICATED&quot; == &quot;true&quot; ]]; then
    DEPLOY_CMD=&quot;$DEPLOY_CMD --allow-unauthenticated&quot;
fi

# 5. 배포 실행
log_info &quot;Deploying to Cloud Run...&quot;
eval $DEPLOY_CMD
log_success &quot;Deployment completed successfully&quot;

# 6. 서비스 URL 확인
SERVICE_URL=$(gcloud run services describe $SERVICE_NAME --region=$REGION --format=&quot;value(status.url)&quot;)
log_success &quot;Service is available at: $SERVICE_URL&quot;

# 7. 배포 정보 출력
log_info &quot;Deployment Summary:&quot;
