💻 런북 통합 알림 템플릿
# 📊 런북 연동 알림 템플릿
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: runbook-integrated-alerts
  namespace: monitoring
spec:
  groups:
  - name: infrastructure.rules
    rules:
    - alert: HighCPUUsage
      expr: (100 - (avg by(instance) (irate(node_cpu_seconds_total{mode=&quot;idle&quot;}[5m])) * 100)) &gt; 90
      for: 5m
      labels:
        severity: critical
        team: infrastructure
        runbook_url: &quot;runbooks.company.com/cpu-high-usage&quot;
        playbook_id: &quot;INFRA-001&quot;
        auto_remediation: &quot;scale_out&quot;
      annotations:
        summary: &quot;노드 {{ $labels.instance }} CPU 사용률 위험 수준&quot;
        description: |
          CPU 사용률이 {{ $value }}%로 위험 수준입니다.

          📋 즉시 조치 사항:
          1. 현재 워크로드 확인
          2. 자동 스케일링 상태 점검  
          3. 리소스 할당 재조정 고려

          🔗 상세 가이드: {{ $labels.runbook_url }}
        dashboard_url: &quot;grafana.company.com/d/node-overview/{{ $labels.instance }}&quot;
        escalation_time: &quot;5분&quot;

