Terraform/01_AWS/AWS-Provider-기초.content:
☁️ Terraform AWS Provider 기초



                  문서 목적 



AWS에서 가장 많이 사용하는 리소스들의 Terraform 코드 블럭을 제공합니다.
복사-붙여넣기하여 바로 사용 가능한 실전 스니펫 모음입니다.


📑 목차

Provider 설정
VPC &amp; 네트워킹
Compute (EC2, ASG)
Container (ECS, EKS)
Database
Storage
Security
Load Balancing


1. Provider 설정
🔧 기본 Provider 설정
# 📊 Terraform 블럭
terraform {
  required_version = &quot;&gt;= 1.0&quot;

  required_providers {
    aws = {
      source  = &quot;hashicorp/aws&quot;
      version = &quot;~&gt; 5.0&quot;
    }
  }
}

# 📊 Provider 설정 - 단일 리전
provider &quot;aws&quot; {
  region = &quot;ap-northeast-2&quot;  # 서울 리전
}
🌍 멀티 리전 설정
# 📊 기본 리전 (서울)
provider &quot;aws&quot; {
  alias  = &quot;seoul&quot;
  region = &quot;ap-northeast-2&quot;
}

# 📊 보조 리전 (도쿄) - DR용
provider &quot;aws&quot; {
  alias  = &quot;tokyo&quot;
  region = &quot;ap-northeast-1&quot;
}

# 📊 미국 리전 (버지니아) - 글로벌 서비스용
provider &quot;aws&quot; {
  alias  = &quot;us_east&quot;
  region = &quot;us-east-1&quot;
}

# 사용 예시
resource &quot;aws_instance&quot; &quot;seoul_web&quot; {
  provider = aws.seoul
  # ...
}

resource &quot;aws_instance&quot; &quot;tokyo_web&quot; {
  provider = aws.tokyo
  # ...
}
🔐 자격증명 설정 방법
# 방법 1: AWS CLI 프로필 사용 (권장)
provider &quot;aws&quot; {
  region  = &quot;ap-northeast-2&quot;
  profile = &quot;default&quot;  # ~/.aws/credentials의 프로필
}

# 방법 2: 환경 변수 사용
# 코드 없음, 환경 변수만 설정:
# export AWS_ACCESS_KEY_ID=&quot;...&quot;
# export AWS_SECRET_ACCESS_KEY=&quot;...&quot;
# export AWS_DEFAULT_REGION=&quot;ap-northeast-2&quot;

# 방법 3: 공유 자격증명 파일 경로 지정
provider &quot;aws&quot; {
  region                   = &quot;ap-northeast-2&quot;
  shared_credentials_files = [&quot;~/.aws/credentials&quot;]
  profile                  = &quot;production&quot;
}

# 방법 4: IAM 역할 (EC2/ECS에서 실행 시)
provider &quot;aws&quot; {
  region = &quot;ap-northeast-2&quot;
  # IAM Role이 자동으로 사용됨
}
🏷️ 기본 태그 설정
provider &quot;aws&quot; {
  region = &quot;ap-northeast-2&quot;

  # 모든 리소스에 자동으로 적용될 기본 태그
  default_tags {
    tags = {
      Environment = &quot;Production&quot;
      ManagedBy   = &quot;Terraform&quot;
      Team        = &quot;DevOps&quot;
      Project     = &quot;MyProject&quot;
      CostCenter  = &quot;Engineering&quot;
    }
  }
}

2. VPC &amp; 네트워킹
🌐 VPC 생성
# 📊 VPC
resource &quot;aws_vpc&quot; &quot;main&quot; {
  cidr_block           = &quot;10.0.0.0/16&quot;
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = &quot;main-vpc&quot;
  }
}

# 📊 Internet Gateway
resource &quot;aws_internet_gateway&quot; &quot;main&quot; {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = &quot;main-igw&quot;
  }
}
🔀 서브넷 생성
# 📊 퍼블릭 서브넷
resource &quot;aws_subnet&quot; &quot;public&quot; {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = &quot;10.0.${count.index + 1}.0/24&quot;
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = &quot;public-subnet-${count.index + 1}&quot;
    Type = &quot;Public&quot;
  }
}

# 📊 프라이빗 서브넷
resource &quot;aws_subnet&quot; &quot;private&quot; {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = &quot;10.0.${count.index + 11}.0/24&quot;
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = &quot;private-subnet-${count.index + 1}&quot;
    Type = &quot;Private&quot;
  }
}

# 📊 가용 영역 데이터 소스
data &quot;aws_availability_zones&quot; &quot;available&quot; {
  state = &quot;available&quot;
}
🛣️ 라우트 테이블
# 📊 퍼블릭 라우트 테이블
resource &quot;aws_route_table&quot; &quot;public&quot; {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = &quot;0.0.0.0/0&quot;
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = &quot;public-rt&quot;
  }
}

# 📊 라우트 테이블 연결
resource &quot;aws_route_table_association&quot; &quot;public&quot; {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}
🔒 보안 그룹
# 📊 웹 서버 보안 그룹
resource &quot;aws_security_group&quot; &quot;web&quot; {
  name        = &quot;web-sg&quot;
  description = &quot;Security group for web servers&quot;
  vpc_id      = aws_vpc.main.id

  # HTTP 인바운드
  ingress {
    description = &quot;HTTP from anywhere&quot;
    from_port   = 80
    to_port     = 80
    protocol    = &quot;tcp&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  # HTTPS 인바운드
  ingress {
    description = &quot;HTTPS from anywhere&quot;
    from_port   = 443
    to_port     = 443
    protocol    = &quot;tcp&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  # SSH 인바운드 (특정 IP만)
  ingress {
    description = &quot;SSH from office&quot;
    from_port   = 22
    to_port     = 22
    protocol    = &quot;tcp&quot;
    cidr_blocks = [&quot;1.2.3.4/32&quot;]  # 본인 IP로 변경
  }

  # 모든 아웃바운드
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = &quot;-1&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  tags = {
    Name = &quot;web-sg&quot;
  }
}

# 📊 데이터베이스 보안 그룹
resource &quot;aws_security_group&quot; &quot;database&quot; {
  name        = &quot;database-sg&quot;
  description = &quot;Security group for database&quot;
  vpc_id      = aws_vpc.main.id

  # MySQL/MariaDB (웹 서버에서만 접근)
  ingress {
    description     = &quot;MySQL from web servers&quot;
    from_port       = 3306
    to_port         = 3306
    protocol        = &quot;tcp&quot;
    security_groups = [aws_security_group.web.id]
  }

  # PostgreSQL (웹 서버에서만 접근)
  ingress {
    description     = &quot;PostgreSQL from web servers&quot;
    from_port       = 5432
    to_port         = 5432
    protocol        = &quot;tcp&quot;
    security_groups = [aws_security_group.web.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = &quot;-1&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  tags = {
    Name = &quot;database-sg&quot;
  }
}
🌉 NAT Gateway
# 📊 Elastic IP for NAT Gateway
resource &quot;aws_eip&quot; &quot;nat&quot; {
  count  = 1
  domain = &quot;vpc&quot;

  tags = {
    Name = &quot;nat-eip&quot;
  }

  depends_on = [aws_internet_gateway.main]
}

# 📊 NAT Gateway
resource &quot;aws_nat_gateway&quot; &quot;main&quot; {
  count         = 1
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = &quot;main-nat-gw&quot;
  }

  depends_on = [aws_internet_gateway.main]
}

# 📊 프라이빗 라우트 테이블 (NAT Gateway 사용)
resource &quot;aws_route_table&quot; &quot;private&quot; {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = &quot;0.0.0.0/0&quot;
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name = &quot;private-rt&quot;
  }
}

# 📊 프라이빗 서브넷 라우트 테이블 연결
resource &quot;aws_route_table_association&quot; &quot;private&quot; {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

3. Compute (EC2, Auto Scaling)
🖥️ EC2 인스턴스
# 📊 최신 Amazon Linux 2023 AMI 조회
data &quot;aws_ami&quot; &quot;amazon_linux_2023&quot; {
  most_recent = true
  owners      = [&quot;amazon&quot;]

  filter {
    name   = &quot;name&quot;
    values = [&quot;al2023-ami-*-x86_64&quot;]
  }

  filter {
    name   = &quot;virtualization-type&quot;
    values = [&quot;hvm&quot;]
  }
}

# 📊 EC2 인스턴스
resource &quot;aws_instance&quot; &quot;web&quot; {
  ami           = data.aws_ami.amazon_linux_2023.id
  instance_type = &quot;t3.micro&quot;

  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = true

  # 키 페어
  key_name = &quot;my-keypair&quot;

  # 사용자 데이터 (부팅 시 실행)
  user_data = &lt;&lt;-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              echo &quot;&lt;h1&gt;Hello from Terraform!&lt;/h1&gt;&quot; &gt; /var/www/html/index.html
              EOF

  # 루트 볼륨 설정
  root_block_device {
    volume_size = 20
    volume_type = &quot;gp3&quot;
    encrypted   = true
    delete_on_termination = true
  }

  # 추가 EBS 볼륨
  ebs_block_device {
    device_name = &quot;/dev/sdf&quot;
    volume_size = 100
    volume_type = &quot;gp3&quot;
    encrypted   = true
  }

  tags = {
    Name = &quot;web-server&quot;
    Role = &quot;WebServer&quot;
  }

  lifecycle {
    create_before_destroy = true
  }
}
🚀 Launch Template
# 📊 Launch Template
resource &quot;aws_launch_template&quot; &quot;web&quot; {
  name_prefix   = &quot;web-&quot;
  image_id      = data.aws_ami.amazon_linux_2023.id
  instance_type = &quot;t3.micro&quot;

  vpc_security_group_ids = [aws_security_group.web.id]

  key_name = &quot;my-keypair&quot;

  user_data = base64encode(&lt;&lt;-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              INSTANCE_ID=$(ec2-metadata --instance-id | cut -d &quot; &quot; -f 2)
              echo &quot;&lt;h1&gt;Server: $INSTANCE_ID&lt;/h1&gt;&quot; &gt; /var/www/html/index.html
              EOF
  )

  block_device_mappings {
    device_name = &quot;/dev/xvda&quot;

    ebs {
      volume_size = 20
      volume_type = &quot;gp3&quot;
      encrypted   = true
      delete_on_termination = true
    }
  }

  monitoring {
    enabled = true
  }

  tag_specifications {
    resource_type = &quot;instance&quot;

    tags = {
      Name = &quot;web-asg-instance&quot;
    }
  }
}
📈 Auto Scaling Group
# 📊 Auto Scaling Group
resource &quot;aws_autoscaling_group&quot; &quot;web&quot; {
  name                = &quot;web-asg&quot;
  desired_capacity    = 2
  min_size            = 1
  max_size            = 5
  health_check_type   = &quot;ELB&quot;
  health_check_grace_period = 300

  vpc_zone_identifier = aws_subnet.private[*].id
  target_group_arns   = [aws_lb_target_group.web.arn]

  launch_template {
    id      = aws_launch_template.web.id
    version = &quot;$Latest&quot;
  }

  tag {
    key                 = &quot;Name&quot;
    value               = &quot;web-asg-instance&quot;
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
  }
}

# 📊 Auto Scaling Policy - CPU 기반
resource &quot;aws_autoscaling_policy&quot; &quot;cpu_scale_up&quot; {
  name                   = &quot;cpu-scale-up&quot;
  autoscaling_group_name = aws_autoscaling_group.web.name
  adjustment_type        = &quot;ChangeInCapacity&quot;
  scaling_adjustment     = 1
  cooldown               = 300
}

resource &quot;aws_autoscaling_policy&quot; &quot;cpu_scale_down&quot; {
  name                   = &quot;cpu-scale-down&quot;
  autoscaling_group_name = aws_autoscaling_group.web.name
  adjustment_type        = &quot;ChangeInCapacity&quot;
  scaling_adjustment     = -1
  cooldown               = 300
}

# 📊 CloudWatch Alarm - Scale Up
resource &quot;aws_cloudwatch_metric_alarm&quot; &quot;cpu_high&quot; {
  alarm_name          = &quot;web-cpu-high&quot;
  comparison_operator = &quot;GreaterThanThreshold&quot;
  evaluation_periods  = 2
  metric_name         = &quot;CPUUtilization&quot;
  namespace           = &quot;AWS/EC2&quot;
  period              = 120
  statistic           = &quot;Average&quot;
  threshold           = 70

  dimensions = {
    AutoScalingGroupName = aws_autoscaling_group.web.name
  }

  alarm_actions = [aws_autoscaling_policy.cpu_scale_up.arn]
}

# 📊 CloudWatch Alarm - Scale Down
resource &quot;aws_cloudwatch_metric_alarm&quot; &quot;cpu_low&quot; {
  alarm_name          = &quot;web-cpu-low&quot;
  comparison_operator = &quot;LessThanThreshold&quot;
  evaluation_periods  = 2
  metric_name         = &quot;CPUUtilization&quot;
  namespace           = &quot;AWS/EC2&quot;
  period              = 120
  statistic           = &quot;Average&quot;
  threshold           = 30

  dimensions = {
    AutoScalingGroupName = aws_autoscaling_group.web.name
  }

  alarm_actions = [aws_autoscaling_policy.cpu_scale_down.arn]
}

# 📊 Auto Scaling Schedule - 업무시간 스케일링
resource &quot;aws_autoscaling_schedule&quot; &quot;scale_up_morning&quot; {
  scheduled_action_name  = &quot;scale-up-morning&quot;
  min_size               = 2
  max_size               = 5
  desired_capacity       = 3
  recurrence             = &quot;0 9 * * 1-5&quot;  # 평일 09:00
  autoscaling_group_name = aws_autoscaling_group.web.name
}

resource &quot;aws_autoscaling_schedule&quot; &quot;scale_down_evening&quot; {
  scheduled_action_name  = &quot;scale-down-evening&quot;
  min_size               = 1
  max_size               = 2
  desired_capacity       = 1
  recurrence             = &quot;0 18 * * 1-5&quot;  # 평일 18:00
  autoscaling_group_name = aws_autoscaling_group.web.name
}

4. Container (ECS, EKS)
🐳 ECS Fargate
# 📊 ECS 클러스터
resource &quot;aws_ecs_cluster&quot; &quot;main&quot; {
  name = &quot;main-cluster&quot;

  setting {
    name  = &quot;containerInsights&quot;
    value = &quot;enabled&quot;
  }

  tags = {
    Name = &quot;main-ecs-cluster&quot;
  }
}

# 📊 CloudWatch Logs 그룹
resource &quot;aws_cloudwatch_log_group&quot; &quot;app&quot; {
  name              = &quot;/ecs/my-app&quot;
  retention_in_days = 7

  tags = {
    Name = &quot;my-app-logs&quot;
  }
}

# 📊 ECS Task Definition
resource &quot;aws_ecs_task_definition&quot; &quot;app&quot; {
  family                   = &quot;my-app&quot;
  network_mode             = &quot;awsvpc&quot;
  requires_compatibilities = [&quot;FARGATE&quot;]
  cpu                      = &quot;256&quot;
  memory                   = &quot;512&quot;
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = &quot;my-app&quot;
      image     = &quot;nginx:latest&quot;
      essential = true

      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = &quot;tcp&quot;
        }
      ]

      logConfiguration = {
        logDriver = &quot;awslogs&quot;
        options = {
          &quot;awslogs-group&quot;         = aws_cloudwatch_log_group.app.name
          &quot;awslogs-region&quot;        = &quot;ap-northeast-2&quot;
          &quot;awslogs-stream-prefix&quot; = &quot;ecs&quot;
        }
      }

      environment = [
        {
          name  = &quot;ENVIRONMENT&quot;
          value = &quot;production&quot;
        }
      ]
    }
  ])

  tags = {
    Name = &quot;my-app-task&quot;
  }
}

# 📊 ECS Service
resource &quot;aws_ecs_service&quot; &quot;app&quot; {
  name            = &quot;my-app-service&quot;
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2
  launch_type     = &quot;FARGATE&quot;

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.web.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.web.arn
    container_name   = &quot;my-app&quot;
    container_port   = 80
  }

  depends_on = [aws_lb_listener.web]
}

# 📊 ECS Execution Role
resource &quot;aws_iam_role&quot; &quot;ecs_execution&quot; {
