5. Database
🗄️ RDS (MySQL/PostgreSQL)
# 📊 RDS Subnet Group
resource &quot;aws_db_subnet_group&quot; &quot;main&quot; {
  name       = &quot;main-db-subnet-group&quot;
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = &quot;main-db-subnet-group&quot;
  }
}

# 📊 RDS Parameter Group
resource &quot;aws_db_parameter_group&quot; &quot;mysql&quot; {
  name   = &quot;mysql-params&quot;
  family = &quot;mysql8.0&quot;

  parameter {
    name  = &quot;character_set_server&quot;
    value = &quot;utf8mb4&quot;
  }

  parameter {
    name  = &quot;collation_server&quot;
    value = &quot;utf8mb4_unicode_ci&quot;
  }

  tags = {
    Name = &quot;mysql-params&quot;
  }
}

# 📊 RDS Instance
resource &quot;aws_db_instance&quot; &quot;main&quot; {
  identifier     = &quot;main-db&quot;
  engine         = &quot;mysql&quot;
  engine_version = &quot;8.0&quot;
  instance_class = &quot;db.t3.micro&quot;

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = &quot;gp3&quot;
  storage_encrypted     = true

  db_name  = &quot;myapp&quot;
  username = &quot;admin&quot;
  password = var.db_password  # 변수로 관리 (절대 하드코딩 금지!)

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  backup_retention_period = 7
  backup_window           = &quot;03:00-04:00&quot;
  maintenance_window      = &quot;sun:04:00-sun:05:00&quot;

  skip_final_snapshot       = false
  final_snapshot_identifier = &quot;main-db-final-snapshot&quot;

  enabled_cloudwatch_logs_exports = [&quot;error&quot;, &quot;general&quot;, &quot;slowquery&quot;]

  tags = {
    Name = &quot;main-db&quot;
  }
}

# 📊 RDS Read Replica
resource &quot;aws_db_instance&quot; &quot;replica&quot; {
  identifier     = &quot;main-db-replica&quot;
  replicate_source_db = aws_db_instance.main.identifier
  instance_class = &quot;db.t3.micro&quot;

  skip_final_snapshot = true

  tags = {
    Name = &quot;main-db-replica&quot;
  }
}
⚡ DynamoDB
# 📊 DynamoDB 테이블
resource &quot;aws_dynamodb_table&quot; &quot;users&quot; {
  name           = &quot;users&quot;
  billing_mode   = &quot;PAY_PER_REQUEST&quot;  # 또는 &quot;PROVISIONED&quot;
  hash_key       = &quot;user_id&quot;
  range_key      = &quot;timestamp&quot;

  attribute {
    name = &quot;user_id&quot;
    type = &quot;S&quot;  # String
  }

  attribute {
    name = &quot;timestamp&quot;
    type = &quot;N&quot;  # Number
  }

  attribute {
    name = &quot;email&quot;
    type = &quot;S&quot;
  }

  # Global Secondary Index
  global_secondary_index {
    name            = &quot;EmailIndex&quot;
    hash_key        = &quot;email&quot;
    projection_type = &quot;ALL&quot;
  }

  # Point-in-time Recovery
  point_in_time_recovery {
    enabled = true
  }

  # 서버 측 암호화
  server_side_encryption {
    enabled = true
  }

  # Time to Live
  ttl {
    attribute_name = &quot;expiration_time&quot;
    enabled        = true
  }

  tags = {
    Name = &quot;users-table&quot;
  }
}

# 📊 DynamoDB 테이블 (Provisioned 모드)
resource &quot;aws_dynamodb_table&quot; &quot;sessions&quot; {
  name           = &quot;sessions&quot;
  billing_mode   = &quot;PROVISIONED&quot;
  read_capacity  = 5
  write_capacity = 5
  hash_key       = &quot;session_id&quot;

  attribute {
    name = &quot;session_id&quot;
    type = &quot;S&quot;
  }

  # Auto Scaling
  tags = {
    Name = &quot;sessions-table&quot;
  }
}

# 📊 DynamoDB Auto Scaling - Read
resource &quot;aws_appautoscaling_target&quot; &quot;dynamodb_read&quot; {
  max_capacity       = 100
  min_capacity       = 5
  resource_id        = &quot;table/${aws_dynamodb_table.sessions.name}&quot;
  scalable_dimension = &quot;dynamodb:table:ReadCapacityUnits&quot;
  service_namespace  = &quot;dynamodb&quot;
}

resource &quot;aws_appautoscaling_policy&quot; &quot;dynamodb_read_policy&quot; {
  name               = &quot;DynamoDBReadCapacityUtilization:${aws_appautoscaling_target.dynamodb_read.resource_id}&quot;
  policy_type        = &quot;TargetTrackingScaling&quot;
  resource_id        = aws_appautoscaling_target.dynamodb_read.resource_id
  scalable_dimension = aws_appautoscaling_target.dynamodb_read.scalable_dimension
  service_namespace  = aws_appautoscaling_target.dynamodb_read.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = &quot;DynamoDBReadCapacityUtilization&quot;
    }
    target_value = 70.0
  }
}

