3. 코드 작성
📁 프로젝트 구조
terraform-vpc-web/
├── main.tf              # VPC 및 네트워크 리소스
├── ec2.tf               # EC2 인스턴스 및 보안 그룹
├── alb.tf               # Application Load Balancer
├── variables.tf         # 변수 정의
├── outputs.tf           # 출력 정의
└── terraform.tfvars     # 변수 값
📄 variables.tf
# 📋 프로젝트 설정
variable &quot;project_name&quot; {
  description = &quot;프로젝트 이름&quot;
  type        = string
  default     = &quot;terraform-vpc-web&quot;
}

variable &quot;environment&quot; {
  description = &quot;환경 (dev/staging/prod)&quot;
  type        = string
  default     = &quot;dev&quot;
}

# 📋 AWS 설정
variable &quot;aws_region&quot; {
  description = &quot;AWS 리전&quot;
  type        = string
  default     = &quot;ap-northeast-2&quot;
}

variable &quot;availability_zones&quot; {
  description = &quot;가용 영역 목록&quot;
  type        = list(string)
  default     = [&quot;ap-northeast-2a&quot;, &quot;ap-northeast-2c&quot;]
}

# 📋 네트워크 설정
variable &quot;vpc_cidr&quot; {
  description = &quot;VPC CIDR 블록&quot;
  type        = string
  default     = &quot;10.0.0.0/16&quot;
}

variable &quot;public_subnet_cidrs&quot; {
  description = &quot;퍼블릭 서브넷 CIDR 목록&quot;
  type        = list(string)
  default     = [&quot;10.0.1.0/24&quot;, &quot;10.0.2.0/24&quot;]
}

variable &quot;private_subnet_cidrs&quot; {
  description = &quot;프라이빗 서브넷 CIDR 목록&quot;
  type        = list(string)
  default     = [&quot;10.0.11.0/24&quot;, &quot;10.0.12.0/24&quot;]
}

# 📋 EC2 설정
variable &quot;instance_type&quot; {
  description = &quot;EC2 인스턴스 타입&quot;
  type        = string
  default     = &quot;t2.micro&quot;
}

variable &quot;ami_id&quot; {
  description = &quot;Amazon Linux 2023 AMI ID (서울 리전)&quot;
  type        = string
  default     = &quot;ami-0c9c942bd7bf113a2&quot;  # Amazon Linux 2023
}

# 📋 보안 설정
variable &quot;allowed_ssh_cidr&quot; {
  description = &quot;SSH 접속 허용 IP (보안을 위해 본인 IP로 설정)&quot;
  type        = string
  default     = &quot;0.0.0.0/0&quot;  # 실습용 (실제로는 본인 IP 지정!)
}
📄 main.tf
# 📊 Terraform 설정
terraform {
  required_version = &quot;&gt;= 1.0&quot;

  required_providers {
    aws = {
      source  = &quot;hashicorp/aws&quot;
      version = &quot;~&gt; 5.0&quot;
    }
  }
}

provider &quot;aws&quot; {
  region = var.aws_region
}

# 📊 VPC 생성
resource &quot;aws_vpc&quot; &quot;main&quot; {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = &quot;${var.project_name}-vpc&quot;
    Environment = var.environment
    ManagedBy   = &quot;Terraform&quot;
  }
}

# 📊 Internet Gateway
resource &quot;aws_internet_gateway&quot; &quot;main&quot; {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = &quot;${var.project_name}-igw&quot;
    Environment = var.environment
  }
}

# 📊 퍼블릭 서브넷
resource &quot;aws_subnet&quot; &quot;public&quot; {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = &quot;${var.project_name}-public-subnet-${count.index + 1}&quot;
    Environment = var.environment
    Type        = &quot;Public&quot;
  }
}

# 📊 프라이빗 서브넷
resource &quot;aws_subnet&quot; &quot;private&quot; {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = {
    Name        = &quot;${var.project_name}-private-subnet-${count.index + 1}&quot;
    Environment = var.environment
    Type        = &quot;Private&quot;
  }
}

# 📊 EIP for NAT Gateway
resource &quot;aws_eip&quot; &quot;nat&quot; {
  domain = &quot;vpc&quot;

  tags = {
    Name        = &quot;${var.project_name}-nat-eip&quot;
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.main]
}

# 📊 NAT Gateway
resource &quot;aws_nat_gateway&quot; &quot;main&quot; {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = &quot;${var.project_name}-nat-gw&quot;
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.main]
}

# 📊 퍼블릭 라우트 테이블
resource &quot;aws_route_table&quot; &quot;public&quot; {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = &quot;0.0.0.0/0&quot;
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = &quot;${var.project_name}-public-rt&quot;
    Environment = var.environment
  }
}

# 📊 프라이빗 라우트 테이블
resource &quot;aws_route_table&quot; &quot;private&quot; {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = &quot;0.0.0.0/0&quot;
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name        = &quot;${var.project_name}-private-rt&quot;
    Environment = var.environment
  }
}

# 📊 퍼블릭 서브넷 라우트 테이블 연결
resource &quot;aws_route_table_association&quot; &quot;public&quot; {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# 📊 프라이빗 서브넷 라우트 테이블 연결
resource &quot;aws_route_table_association&quot; &quot;private&quot; {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}
📄 ec2.tf
# 📊 웹 서버 보안 그룹
resource &quot;aws_security_group&quot; &quot;web&quot; {
  name        = &quot;${var.project_name}-web-sg&quot;
  description = &quot;Security group for web servers&quot;
  vpc_id      = aws_vpc.main.id

  # HTTP from ALB
  ingress {
    description     = &quot;HTTP from ALB&quot;
    from_port       = 80
    to_port         = 80
    protocol        = &quot;tcp&quot;
    security_groups = [aws_security_group.alb.id]
  }

  # SSH from allowed CIDR
  ingress {
    description = &quot;SSH from allowed IP&quot;
    from_port   = 22
    to_port     = 22
    protocol    = &quot;tcp&quot;
    cidr_blocks = [var.allowed_ssh_cidr]
  }

  # All outbound
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = &quot;-1&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  tags = {
    Name        = &quot;${var.project_name}-web-sg&quot;
    Environment = var.environment
  }
}

# 📊 EC2 인스턴스 (웹 서버)
resource &quot;aws_instance&quot; &quot;web&quot; {
  count                  = length(var.availability_zones)
  ami                    = var.ami_id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.public[count.index].id
  vpc_security_group_ids = [aws_security_group.web.id]

  user_data = &lt;&lt;-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd

              # 인스턴스 정보 표시
              INSTANCE_ID=$(ec2-metadata --instance-id | cut -d &quot; &quot; -f 2)
              AZ=$(ec2-metadata --availability-zone | cut -d &quot; &quot; -f 2)

              cat &gt; /var/www/html/index.html &lt;&lt;HTML
              &lt;!DOCTYPE html&gt;
              &lt;html&gt;
              &lt;head&gt;
                  &lt;title&gt;Terraform Web Server&lt;/title&gt;
                  &lt;style&gt;
                      body {
                          font-family: Arial, sans-serif;
                          max-width: 800px;
                          margin: 50px auto;
                          padding: 20px;
