📄 alb.tf
# 📊 ALB 보안 그룹
resource &quot;aws_security_group&quot; &quot;alb&quot; {
  name        = &quot;${var.project_name}-alb-sg&quot;
  description = &quot;Security group for Application Load Balancer&quot;
  vpc_id      = aws_vpc.main.id

  # HTTP from anywhere
  ingress {
    description = &quot;HTTP from internet&quot;
    from_port   = 80
    to_port     = 80
    protocol    = &quot;tcp&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  # All outbound
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = &quot;-1&quot;
    cidr_blocks = [&quot;0.0.0.0/0&quot;]
  }

  tags = {
    Name        = &quot;${var.project_name}-alb-sg&quot;
    Environment = var.environment
  }
}

# 📊 Application Load Balancer
resource &quot;aws_lb&quot; &quot;main&quot; {
  name               = &quot;${var.project_name}-alb&quot;
  internal           = false
  load_balancer_type = &quot;application&quot;
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = false

  tags = {
    Name        = &quot;${var.project_name}-alb&quot;
    Environment = var.environment
  }
}

# 📊 타겟 그룹
resource &quot;aws_lb_target_group&quot; &quot;web&quot; {
  name     = &quot;${var.project_name}-tg&quot;
  port     = 80
  protocol = &quot;HTTP&quot;
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    healthy_threshold   = 2
    interval            = 30
    matcher             = &quot;200&quot;
    path                = &quot;/&quot;
    port                = &quot;traffic-port&quot;
    protocol            = &quot;HTTP&quot;
    timeout             = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name        = &quot;${var.project_name}-tg&quot;
    Environment = var.environment
  }
}

# 📊 타겟 그룹에 EC2 인스턴스 등록
resource &quot;aws_lb_target_group_attachment&quot; &quot;web&quot; {
  count            = length(aws_instance.web)
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = aws_instance.web[count.index].id
  port             = 80
}

# 📊 리스너
resource &quot;aws_lb_listener&quot; &quot;web&quot; {
  load_balancer_arn = aws_lb.main.arn
  port              = &quot;80&quot;
  protocol          = &quot;HTTP&quot;

  default_action {
    type             = &quot;forward&quot;
    target_group_arn = aws_lb_target_group.web.arn
  }
}
📄 outputs.tf
# 📤 VPC 정보
output &quot;vpc_id&quot; {
  description = &quot;VPC ID&quot;
  value       = aws_vpc.main.id
}

output &quot;vpc_cidr&quot; {
  description = &quot;VPC CIDR 블록&quot;
  value       = aws_vpc.main.cidr_block
}

# 📤 서브넷 정보
output &quot;public_subnet_ids&quot; {
  description = &quot;퍼블릭 서브넷 ID 목록&quot;
  value       = aws_subnet.public[*].id
}

output &quot;private_subnet_ids&quot; {
  description = &quot;프라이빗 서브넷 ID 목록&quot;
  value       = aws_subnet.private[*].id
}

# 📤 EC2 정보
output &quot;web_server_ids&quot; {
  description = &quot;웹 서버 인스턴스 ID 목록&quot;
  value       = aws_instance.web[*].id
}

output &quot;web_server_public_ips&quot; {
  description = &quot;웹 서버 공인 IP 목록&quot;
  value       = aws_instance.web[*].public_ip
}

# 📤 ALB 정보
output &quot;alb_dns_name&quot; {
  description = &quot;Application Load Balancer DNS 이름&quot;
  value       = aws_lb.main.dns_name
}

output &quot;website_url&quot; {
  description = &quot;웹사이트 접속 URL&quot;
  value       = &quot;http://${aws_lb.main.dns_name}&quot;
}

# 📤 보안 그룹 정보
output &quot;web_security_group_id&quot; {
  description = &quot;웹 서버 보안 그룹 ID&quot;
  value       = aws_security_group.web.id
}

output &quot;alb_security_group_id&quot; {
  description = &quot;ALB 보안 그룹 ID&quot;
  value       = aws_security_group.alb.id
}

4. 실행 및 테스트
🚀 배포하기
# 1. 프로젝트 디렉토리 생성
mkdir ~/terraform-vpc-web
cd ~/terraform-vpc-web

# 2. 위 파일들 생성 (main.tf, ec2.tf, alb.tf, variables.tf, outputs.tf)

# 3. 초기화
terraform init
예상 출력:
Initializing the backend...
Initializing provider plugins...
- Finding hashicorp/aws versions matching &quot;~&gt; 5.0&quot;...
- Installing hashicorp/aws v5.31.0...

Terraform has been successfully initialized!

# 4. 코드 검증
terraform validate
# 5. 포맷팅
terraform fmt
# 6. 실행 계획
terraform plan
예상 출력:
Plan: 24 to add, 0 to change, 0 to destroy.

Changes to Outputs:
  + alb_dns_name           = (known after apply)
  + public_subnet_ids      = [
      + (known after apply),
      + (known after apply),
    ]
  + vpc_id                 = (known after apply)
  + web_server_public_ips  = [
      + (known after apply),
      + (known after apply),
    ]
  + website_url            = (known after apply)

# 7. 배포 (약 5-7분 소요)
terraform apply
입력:
Do you want to perform these actions?
  Enter a value: yes

배포 완료 출력:
Apply complete! Resources: 24 added, 0 changed, 0 destroyed.

Outputs:

alb_dns_name = &quot;terraform-vpc-web-alb-1234567890.ap-northeast-2.elb.amazonaws.com&quot;
public_subnet_ids = [
  &quot;subnet-0abcd1234efgh5678&quot;,
  &quot;subnet-0ijkl9012mnop3456&quot;,
]
vpc_id = &quot;vpc-0qrst5678uvwx9012&quot;
web_server_public_ips = [
  &quot;52.79.123.45&quot;,
  &quot;52.79.234.56&quot;,
]
website_url = &quot;terraform-vpc-web-alb-1234567890.ap-northeast-2.elb.amazonaws.com&quot;

🧪 테스트하기
# 1. 웹사이트 접속 URL 확인
terraform output website_url
브라우저에서 접속:

URL 복사하여 브라우저에서 열기
“Terraform으로 구축한 웹 서버” 페이지 확인
새로고침할 때마다 다른 서버(Web Server 1 또는 2) 표시 확인

# 2. curl로 테스트
curl $(terraform output -raw website_url)

# 3. 여러 번 요청하여 로드 밸런싱 확인
for i in {1..10}; do
  curl -s $(terraform output -raw website_url) | grep &quot;서버:&quot;
  sleep 1
done
# 4. AWS CLI로 리소스 확인
# VPC 확인
aws ec2 describe-vpcs --vpc-ids $(terraform output -raw vpc_id)

# EC2 인스턴스 확인
aws ec2 describe-instances --filters &quot;Name=tag:Name,Values=terraform-vpc-web-web-*&quot;

# ALB 확인
aws elbv2 describe-load-balancers --names terraform-vpc-web-alb

# 타겟 그룹 헬스 체크
aws elbv2 describe-target-health --target-group-arn $(aws elbv2 describe-target-groups --names terraform-vpc-web-tg --query &#039;TargetGroups[0].TargetGroupArn&#039; --output text)
🗑️ 정리하기



