예상 소요 시간: 약 3-5분

5. 고급 기능
🔧 변수 파일 활용
terraform.tfvars
# 프로젝트 설정
project_name = &quot;my-web-app&quot;
environment  = &quot;production&quot;

# 네트워크 설정
vpc_cidr             = &quot;10.1.0.0/16&quot;
public_subnet_cidrs  = [&quot;10.1.1.0/24&quot;, &quot;10.1.2.0/24&quot;]
private_subnet_cidrs = [&quot;10.1.11.0/24&quot;, &quot;10.1.12.0/24&quot;]

# 보안 설정 (본인 IP로 변경!)
allowed_ssh_cidr = &quot;123.456.789.0/32&quot;

# EC2 설정
