Terraform/03_Azure/Azure-Provider-기초.content:
☁️ Terraform Azure Provider 기초



                  문서 목적 



Microsoft Azure에서 가장 많이 사용하는 리소스들의 Terraform 코드 블럭을 제공합니다.
복사-붙여넣기하여 바로 사용 가능한 실전 스니펫 모음입니다.


📑 목차

Provider 설정
Virtual Machines
AKS
Container Instances
Database
Storage
Networking
Security &amp; IAM


1. Provider 설정
🔧 기본 Provider 설정
# 📊 Terraform 블럭
terraform {
  required_version = &quot;&gt;= 1.0&quot;

  required_providers {
    azurerm = {
      source  = &quot;hashicorp/azurerm&quot;
      version = &quot;~&gt; 3.0&quot;
    }
  }
}

# 📊 Provider 설정
provider &quot;azurerm&quot; {
  features {}
}
🔐 자격증명 설정
# 방법 1: Azure CLI 인증 (권장 - 로컬 개발)
# az login
provider &quot;azurerm&quot; {
  features {}
}

# 방법 2: 서비스 프린시pal (CI/CD)
provider &quot;azurerm&quot; {
  features {}

  subscription_id = var.subscription_id
  client_id       = var.client_id
  client_secret   = var.client_secret
  tenant_id       = var.tenant_id
}

# 방법 3: 환경 변수 사용
# export ARM_SUBSCRIPTION_ID=&quot;...&quot;
# export ARM_CLIENT_ID=&quot;...&quot;
# export ARM_CLIENT_SECRET=&quot;...&quot;
# export ARM_TENANT_ID=&quot;...&quot;
provider &quot;azurerm&quot; {
  features {}
}
🌍 멀티 Subscription 설정
# 📊 프로덕션 Subscription
provider &quot;azurerm&quot; {
  alias           = &quot;prod&quot;
  subscription_id = &quot;xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx&quot;
  features {}
}

# 📊 개발 Subscription
provider &quot;azurerm&quot; {
  alias           = &quot;dev&quot;
  subscription_id = &quot;yyyyyyyy-yyyy-yyyy-yyyy-yyyyyyyyyyyy&quot;
  features {}
}

# 사용 예시
resource &quot;azurerm_resource_group&quot; &quot;prod_rg&quot; {
  provider = azurerm.prod
  name     = &quot;prod-resources&quot;
  location = &quot;Korea Central&quot;
}

2. Virtual Machines
📦 Resource Group (필수!)
# 📊 Resource Group (Azure의 모든 리소스는 RG 안에 생성)
resource &quot;azurerm_resource_group&quot; &quot;main&quot; {
  name     = &quot;main-resources&quot;
  location = &quot;Korea Central&quot;  # 한국 중부 리전

  tags = {
    environment = &quot;production&quot;
    managed_by  = &quot;terraform&quot;
  }
}
🖥️ Linux Virtual Machine
# 📊 Virtual Network (네트워크 인터페이스 생성 전 필요)
resource &quot;azurerm_virtual_network&quot; &quot;main&quot; {
  name                = &quot;main-vnet&quot;
  address_space       = [&quot;10.0.0.0/16&quot;]
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
}

# 📊 Subnet
resource &quot;azurerm_subnet&quot; &quot;main&quot; {
  name                 = &quot;main-subnet&quot;
  resource_group_name  = azurerm_resource_group.main.name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = [&quot;10.0.1.0/24&quot;]
}

# 📊 Network Interface
resource &quot;azurerm_network_interface&quot; &quot;main&quot; {
  name                = &quot;main-nic&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name

  ip_configuration {
    name                          = &quot;internal&quot;
    subnet_id                     = azurerm_subnet.main.id
    private_ip_address_allocation = &quot;Dynamic&quot;
    public_ip_address_id          = azurerm_public_ip.main.id
  }
}

# 📊 Public IP
resource &quot;azurerm_public_ip&quot; &quot;main&quot; {
  name                = &quot;main-pip&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  allocation_method   = &quot;Static&quot;
  sku                 = &quot;Standard&quot;
}

# 📊 Linux Virtual Machine
resource &quot;azurerm_linux_virtual_machine&quot; &quot;main&quot; {
  name                = &quot;main-vm&quot;
  resource_group_name = azurerm_resource_group.main.name
  location            = azurerm_resource_group.main.location
  size                = &quot;Standard_B1s&quot;  # 가장 저렴한 옵션
  admin_username      = &quot;azureuser&quot;

  network_interface_ids = [
    azurerm_network_interface.main.id,
  ]

  # SSH 키 인증
  admin_ssh_key {
    username   = &quot;azureuser&quot;
    public_key = file(&quot;~/.ssh/id_rsa.pub&quot;)
  }

  # OS 디스크
  os_disk {
    name                 = &quot;main-osdisk&quot;
    caching              = &quot;ReadWrite&quot;
    storage_account_type = &quot;Standard_LRS&quot;
    disk_size_gb         = 30
  }

  # 이미지
  source_image_reference {
    publisher = &quot;Canonical&quot;
    offer     = &quot;0001-com-ubuntu-server-jammy&quot;
    sku       = &quot;22_04-lts-gen2&quot;
    version   = &quot;latest&quot;
  }

  # 커스텀 데이터 (부팅 스크립트)
  custom_data = base64encode(&lt;&lt;-EOF
    #!/bin/bash
    apt-get update
    apt-get install -y nginx
    systemctl start nginx
    echo &quot;&lt;h1&gt;Hello from Terraform!&lt;/h1&gt;&quot; &gt; /var/www/html/index.html
  EOF
  )

  tags = {
    environment = &quot;production&quot;
  }
}

# 📊 데이터 디스크
resource &quot;azurerm_managed_disk&quot; &quot;data&quot; {
  name                 = &quot;main-datadisk&quot;
  location             = azurerm_resource_group.main.location
  resource_group_name  = azurerm_resource_group.main.name
  storage_account_type = &quot;Standard_LRS&quot;
  create_option        = &quot;Empty&quot;
  disk_size_gb         = 100
}

resource &quot;azurerm_virtual_machine_data_disk_attachment&quot; &quot;main&quot; {
  managed_disk_id    = azurerm_managed_disk.data.id
  virtual_machine_id = azurerm_linux_virtual_machine.main.id
  lun                = 0
  caching            = &quot;ReadWrite&quot;
}
📈 Virtual Machine Scale Set
# 📊 Load Balancer
resource &quot;azurerm_lb&quot; &quot;main&quot; {
  name                = &quot;main-lb&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  sku                 = &quot;Standard&quot;

  frontend_ip_configuration {
    name                 = &quot;PublicIPAddress&quot;
    public_ip_address_id = azurerm_public_ip.lb.id
  }
}

resource &quot;azurerm_public_ip&quot; &quot;lb&quot; {
  name                = &quot;lb-pip&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  allocation_method   = &quot;Static&quot;
  sku                 = &quot;Standard&quot;
}

resource &quot;azurerm_lb_backend_address_pool&quot; &quot;main&quot; {
  loadbalancer_id = azurerm_lb.main.id
  name            = &quot;BackEndAddressPool&quot;
}

resource &quot;azurerm_lb_probe&quot; &quot;main&quot; {
  loadbalancer_id = azurerm_lb.main.id
  name            = &quot;http-probe&quot;
  port            = 80
  protocol        = &quot;Http&quot;
  request_path    = &quot;/&quot;
}

resource &quot;azurerm_lb_rule&quot; &quot;main&quot; {
  loadbalancer_id                = azurerm_lb.main.id
  name                           = &quot;LBRule&quot;
  protocol                       = &quot;Tcp&quot;
  frontend_port                  = 80
  backend_port                   = 80
  frontend_ip_configuration_name = &quot;PublicIPAddress&quot;
  backend_address_pool_ids       = [azurerm_lb_backend_address_pool.main.id]
  probe_id                       = azurerm_lb_probe.main.id
}

# 📊 VM Scale Set
resource &quot;azurerm_linux_virtual_machine_scale_set&quot; &quot;main&quot; {
  name                = &quot;main-vmss&quot;
  resource_group_name = azurerm_resource_group.main.name
  location            = azurerm_resource_group.main.location
  sku                 = &quot;Standard_B1s&quot;
  instances           = 2
  admin_username      = &quot;azureuser&quot;

  admin_ssh_key {
    username   = &quot;azureuser&quot;
    public_key = file(&quot;~/.ssh/id_rsa.pub&quot;)
  }

  source_image_reference {
    publisher = &quot;Canonical&quot;
    offer     = &quot;0001-com-ubuntu-server-jammy&quot;
    sku       = &quot;22_04-lts-gen2&quot;
    version   = &quot;latest&quot;
  }

  os_disk {
    storage_account_type = &quot;Standard_LRS&quot;
    caching              = &quot;ReadWrite&quot;
  }

  network_interface {
    name    = &quot;main-nic&quot;
    primary = true

    ip_configuration {
      name      = &quot;internal&quot;
      primary   = true
      subnet_id = azurerm_subnet.main.id

      load_balancer_backend_address_pool_ids = [
        azurerm_lb_backend_address_pool.main.id
      ]
    }
  }

  custom_data = base64encode(&lt;&lt;-EOF
    #!/bin/bash
    apt-get update
    apt-get install -y nginx
    HOSTNAME=$(hostname)
    echo &quot;&lt;h1&gt;Server: $HOSTNAME&lt;/h1&gt;&quot; &gt; /var/www/html/index.html
    systemctl start nginx
  EOF
  )
}

# 📊 Autoscale Settings
resource &quot;azurerm_monitor_autoscale_setting&quot; &quot;main&quot; {
  name                = &quot;autoscale-config&quot;
  resource_group_name = azurerm_resource_group.main.name
  location            = azurerm_resource_group.main.location
  target_resource_id  = azurerm_linux_virtual_machine_scale_set.main.id

  profile {
    name = &quot;defaultProfile&quot;

    capacity {
      default = 2
      minimum = 1
      maximum = 10
    }

    rule {
      metric_trigger {
        metric_name        = &quot;Percentage CPU&quot;
        metric_resource_id = azurerm_linux_virtual_machine_scale_set.main.id
        time_grain         = &quot;PT1M&quot;
        statistic          = &quot;Average&quot;
        time_window        = &quot;PT5M&quot;
        time_aggregation   = &quot;Average&quot;
        operator           = &quot;GreaterThan&quot;
        threshold          = 70
      }

      scale_action {
        direction = &quot;Increase&quot;
        type      = &quot;ChangeCount&quot;
        value     = &quot;1&quot;
        cooldown  = &quot;PT1M&quot;
      }
    }

    rule {
      metric_trigger {
        metric_name        = &quot;Percentage CPU&quot;
        metric_resource_id = azurerm_linux_virtual_machine_scale_set.main.id
        time_grain         = &quot;PT1M&quot;
        statistic          = &quot;Average&quot;
        time_window        = &quot;PT5M&quot;
        time_aggregation   = &quot;Average&quot;
        operator           = &quot;LessThan&quot;
        threshold          = 30
      }

      scale_action {
        direction = &quot;Decrease&quot;
        type      = &quot;ChangeCount&quot;
        value     = &quot;1&quot;
        cooldown  = &quot;PT1M&quot;
      }
    }
  }
}

3. Azure Kubernetes Service (AKS)
☸️ AKS 클러스터
# 📊 AKS 클러스터
resource &quot;azurerm_kubernetes_cluster&quot; &quot;main&quot; {
  name                = &quot;main-aks&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  dns_prefix          = &quot;mainaks&quot;
  kubernetes_version  = &quot;1.28&quot;

  # 기본 노드 풀
  default_node_pool {
    name                = &quot;default&quot;
    node_count          = 2
    vm_size             = &quot;Standard_B2s&quot;
    os_disk_size_gb     = 30
    vnet_subnet_id      = azurerm_subnet.aks.id
    enable_auto_scaling = true
    min_count           = 1
    max_count           = 5

    upgrade_settings {
      max_surge = &quot;10%&quot;
    }
  }

  # Identity
  identity {
    type = &quot;SystemAssigned&quot;
  }

  # Network Profile
  network_profile {
    network_plugin    = &quot;azure&quot;
    load_balancer_sku = &quot;standard&quot;
    service_cidr      = &quot;10.1.0.0/16&quot;
    dns_service_ip    = &quot;10.1.0.10&quot;
  }

  # Azure AD RBAC
  azure_active_directory_role_based_access_control {
    managed                = true
    azure_rbac_enabled     = true
    admin_group_object_ids = [var.admin_group_id]
  }

  # 애드온
  oms_agent {
    log_analytics_workspace_id = azurerm_log_analytics_workspace.main.id
  }

  # HTTP Application Routing (비권장 - Ingress Controller 사용 권장)
  http_application_routing_enabled = false

  tags = {
    environment = &quot;production&quot;
  }
}

# 📊 추가 노드 풀
resource &quot;azurerm_kubernetes_cluster_node_pool&quot; &quot;gpu&quot; {
  name                  = &quot;gpu&quot;
  kubernetes_cluster_id = azurerm_kubernetes_cluster.main.id
  vm_size               = &quot;Standard_NC6&quot;
  node_count            = 1

  enable_auto_scaling = true
  min_count           = 0
  max_count           = 3

  node_labels = {
    &quot;workload&quot; = &quot;gpu&quot;
  }

  node_taints = [
    &quot;gpu=true:NoSchedule&quot;
  ]
}

# 📊 Log Analytics Workspace
resource &quot;azurerm_log_analytics_workspace&quot; &quot;main&quot; {
  name                = &quot;main-workspace&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  sku                 = &quot;PerGB2018&quot;
  retention_in_days   = 30
}

4. Container Instances
🐳 Azure Container Instances
# 📊 Container Group
resource &quot;azurerm_container_group&quot; &quot;main&quot; {
  name                = &quot;main-container-group&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  os_type             = &quot;Linux&quot;
  dns_name_label      = &quot;myapp-${random_string.suffix.result}&quot;
  ip_address_type     = &quot;Public&quot;

  container {
    name   = &quot;myapp&quot;
    image  = &quot;nginx:latest&quot;
    cpu    = &quot;0.5&quot;
    memory = &quot;1.0&quot;

    ports {
      port     = 80
      protocol = &quot;TCP&quot;
    }

    environment_variables = {
      &quot;ENVIRONMENT&quot; = &quot;production&quot;
    }

    secure_environment_variables = {
      &quot;API_KEY&quot; = var.api_key
    }

    volume {
      name       = &quot;logs&quot;
      mount_path = &quot;/var/log&quot;
      read_only  = false
      share_name = azurerm_storage_share.logs.name
      storage_account_name = azurerm_storage_account.main.name
      storage_account_key  = azurerm_storage_account.main.primary_access_key
    }
  }

  tags = {
    environment = &quot;production&quot;
  }
}

resource &quot;random_string&quot; &quot;suffix&quot; {
  length  = 8
  special = false
  upper   = false
}

5. Database
🗄️ Azure SQL Database
# 📊 SQL Server
resource &quot;azurerm_mssql_server&quot; &quot;main&quot; {
  name                         = &quot;main-sqlserver&quot;
  resource_group_name          = azurerm_resource_group.main.name
  location                     = azurerm_resource_group.main.location
  version                      = &quot;12.0&quot;
  administrator_login          = &quot;sqladmin&quot;
  administrator_login_password = var.sql_admin_password

  minimum_tls_version = &quot;1.2&quot;

  azuread_administrator {
    login_username = var.aad_admin_login
    object_id      = var.aad_admin_object_id
  }

  tags = {
    environment = &quot;production&quot;
  }
}

# 📊 SQL Database
resource &quot;azurerm_mssql_database&quot; &quot;main&quot; {
  name           = &quot;main-db&quot;
  server_id      = azurerm_mssql_server.main.id
  collation      = &quot;SQL_Latin1_General_CP1_CI_AS&quot;
  license_type   = &quot;LicenseIncluded&quot;
  max_size_gb    = 2
  sku_name       = &quot;S0&quot;  # Standard, 10 DTU
  zone_redundant = false

  # 자동 백업
  short_term_retention_policy {
    retention_days = 7
  }

  long_term_retention_policy {
    weekly_retention  = &quot;P4W&quot;
    monthly_retention = &quot;P12M&quot;
    yearly_retention  = &quot;P5Y&quot;
    week_of_year      = 1
  }

  tags = {
    environment = &quot;production&quot;
  }
}

# 📊 방화벽 규칙
resource &quot;azurerm_mssql_firewall_rule&quot; &quot;allow_azure&quot; {
  name             = &quot;AllowAzureServices&quot;
  server_id        = azurerm_mssql_server.main.id
  start_ip_address = &quot;0.0.0.0&quot;
  end_ip_address   = &quot;0.0.0.0&quot;
}

resource &quot;azurerm_mssql_firewall_rule&quot; &quot;office&quot; {
  name             = &quot;AllowOffice&quot;
  server_id        = azurerm_mssql_server.main.id
  start_ip_address = &quot;1.2.3.4&quot;
  end_ip_address   = &quot;1.2.3.4&quot;
}
🌍 Cosmos DB
# 📊 Cosmos DB Account
resource &quot;azurerm_cosmosdb_account&quot; &quot;main&quot; {
  name                = &quot;main-cosmos&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name
  offer_type          = &quot;Standard&quot;
  kind                = &quot;GlobalDocumentDB&quot;

  consistency_policy {
    consistency_level       = &quot;Session&quot;
    max_interval_in_seconds = 5
    max_staleness_prefix    = 100
  }

  geo_location {
    location          = azurerm_resource_group.main.location
    failover_priority = 0
  }

  geo_location {
    location          = &quot;Japan East&quot;
    failover_priority = 1
  }

  capabilities {
    name = &quot;EnableServerless&quot;
  }
}

# 📊 Cosmos DB SQL Database
resource &quot;azurerm_cosmosdb_sql_database&quot; &quot;main&quot; {
  name                = &quot;myapp&quot;
  resource_group_name = azurerm_cosmosdb_account.main.resource_group_name
  account_name        = azurerm_cosmosdb_account.main.name
}

# 📊 Cosmos DB Container
resource &quot;azurerm_cosmosdb_sql_container&quot; &quot;users&quot; {
  name                = &quot;users&quot;
  resource_group_name = azurerm_cosmosdb_account.main.resource_group_name
  account_name        = azurerm_cosmosdb_account.main.name
  database_name       = azurerm_cosmosdb_sql_database.main.name
  partition_key_path  = &quot;/userId&quot;

  indexing_policy {
    indexing_mode = &quot;consistent&quot;

    included_path {
      path = &quot;/*&quot;
