}

resource &quot;azurerm_subnet&quot; &quot;aks&quot; {
  name                 = &quot;aks-subnet&quot;
  resource_group_name  = azurerm_resource_group.main.name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = [&quot;10.0.10.0/24&quot;]
}
🔒 Network Security Group
# 📊 NSG
resource &quot;azurerm_network_security_group&quot; &quot;web&quot; {
  name                = &quot;web-nsg&quot;
  location            = azurerm_resource_group.main.location
  resource_group_name = azurerm_resource_group.main.name

  # HTTP
  security_rule {
    name                       = &quot;AllowHTTP&quot;
    priority                   = 100
    direction                  = &quot;Inbound&quot;
    access                     = &quot;Allow&quot;
    protocol                   = &quot;Tcp&quot;
    source_port_range          = &quot;*&quot;
    destination_port_range     = &quot;80&quot;
    source_address_prefix      = &quot;*&quot;
    destination_address_prefix = &quot;*&quot;
  }

  # HTTPS
  security_rule {
    name                       = &quot;AllowHTTPS&quot;
    priority                   = 110
    direction                  = &quot;Inbound&quot;
    access                     = &quot;Allow&quot;
    protocol                   = &quot;Tcp&quot;
    source_port_range          = &quot;*&quot;
    destination_port_range     = &quot;443&quot;
    source_address_prefix      = &quot;*&quot;
    destination_address_prefix = &quot;*&quot;
  }

  # SSH (특정 IP만)
  security_rule {
    name                       = &quot;AllowSSH&quot;
    priority                   = 120
    direction                  = &quot;Inbound&quot;
    access                     = &quot;Allow&quot;
    protocol                   = &quot;Tcp&quot;
    source_port_range          = &quot;*&quot;
    destination_port_range     = &quot;22&quot;
    source_address_prefix      = &quot;1.2.3.4/32&quot;
    destination_address_prefix = &quot;*&quot;
  }

  tags = {
    environment = &quot;production&quot;
  }
}

# 📊 NSG Association
resource &quot;azurerm_subnet_network_security_group_association&quot; &quot;web&quot; {
  subnet_id                 = azurerm_subnet.public.id
  network_security_group_id = azurerm_network_security_group.web.id
}
⚖️ Application Gateway
# 📊 Public IP for App Gateway
resource &quot;azurerm_public_ip&quot; &quot;appgw&quot; {
  name                = &quot;appgw-pip&quot;
  resource_group_name = azurerm_resource_group.main.name
  location            = azurerm_resource_group.main.location
  allocation_method   = &quot;Static&quot;
  sku                 = &quot;Standard&quot;
}

# 📊 Application Gateway
resource &quot;azurerm_application_gateway&quot; &quot;main&quot; {
  name                = &quot;main-appgw&quot;
  resource_group_name = azurerm_resource_group.main.name
  location            = azurerm_resource_group.main.location

  sku {
    name     = &quot;Standard_v2&quot;
    tier     = &quot;Standard_v2&quot;
    capacity = 2
  }

  gateway_ip_configuration {
    name      = &quot;gateway-ip-config&quot;
    subnet_id = azurerm_subnet.appgw.id
  }

  frontend_port {
    name = &quot;http-port&quot;
    port = 80
  }

  frontend_ip_configuration {
    name                 = &quot;frontend-ip-config&quot;
    public_ip_address_id = azurerm_public_ip.appgw.id
  }

  backend_address_pool {
    name = &quot;backend-pool&quot;
  }

  backend_http_settings {
    name                  = &quot;http-settings&quot;
    cookie_based_affinity = &quot;Disabled&quot;
    port                  = 80
    protocol              = &quot;Http&quot;
    request_timeout       = 60
  }

  http_listener {
    name                           = &quot;http-listener&quot;
    frontend_ip_configuration_name = &quot;frontend-ip-config&quot;
    frontend_port_name             = &quot;http-port&quot;
    protocol                       = &quot;Http&quot;
  }

  request_routing_rule {
    name                       = &quot;routing-rule&quot;
    rule_type                  = &quot;Basic&quot;
    http_listener_name         = &quot;http-listener&quot;
    backend_address_pool_name  = &quot;backend-pool&quot;
    backend_http_settings_name = &quot;http-settings&quot;
    priority                   = 100
  }

  tags = {
    environment = &quot;production&quot;
  }
}

resource &quot;azurerm_subnet&quot; &quot;appgw&quot; {
  name                 = &quot;appgw-subnet&quot;
  resource_group_name  = azurerm_resource_group.main.name
  virtual_network_name = azurerm_virtual_network.main.name
  address_prefixes     = [&quot;10.0.3.0/24&quot;]
}

8. Security &amp; IAM
🔐 Role Assignment
# 📊 현재 클라이언트 정보 조회
data &quot;azurerm_client_config&quot; &quot;current&quot; {}

# 📊 Role Assignment - Storage Blob Data Contributor
resource &quot;azurerm_role_assignment&quot; &quot;storage&quot; {
  scope                = azurerm_storage_account.main.id
  role_definition_name = &quot;Storage Blob Data Contributor&quot;
  principal_id         = data.azurerm_client_config.current.object_id
}

# 📊 Role Assignment - AKS Cluster Admin
resource &quot;azurerm_role_assignment&quot; &quot;aks_admin&quot; {
  scope                = azurerm_kubernetes_cluster.main.id
  role_definition_name = &quot;Azure Kubernetes Service Cluster Admin Role&quot;
  principal_id         = var.admin_group_id
}
🔑 Key Vault
# 📊 Key Vault
resource &quot;azurerm_key_vault&quot; &quot;main&quot; {
  name                       = &quot;main-kv-${random_string.kv.result}&quot;
  location                   = azurerm_resource_group.main.location
  resource_group_name        = azurerm_resource_group.main.name
  tenant_id                  = data.azurerm_client_config.current.tenant_id
  sku_name                   = &quot;standard&quot;
  soft_delete_retention_days = 7
  purge_protection_enabled   = true

  network_acls {
    bypass         = &quot;AzureServices&quot;
    default_action = &quot;Deny&quot;
    ip_rules       = [&quot;1.2.3.4&quot;]
  }

  tags = {
    environment = &quot;production&quot;
  }
}

resource &quot;random_string&quot; &quot;kv&quot; {
  length  = 8
  special = false
  upper   = false
}

# 📊 Key Vault Access Policy
resource &quot;azurerm_key_vault_access_policy&quot; &quot;main&quot; {
  key_vault_id = azurerm_key_vault.main.id
  tenant_id    = data.azurerm_client_config.current.tenant_id
  object_id    = data.azurerm_client_config.current.object_id

  secret_permissions = [
    &quot;Get&quot;, &quot;List&quot;, &quot;Set&quot;, &quot;Delete&quot;, &quot;Purge&quot;
  ]

  key_permissions = [
    &quot;Get&quot;, &quot;List&quot;, &quot;Create&quot;, &quot;Delete&quot;
  ]

  certificate_permissions = [
    &quot;Get&quot;, &quot;List&quot;, &quot;Create&quot;, &quot;Delete&quot;
  ]
}

# 📊 Key Vault Secret
resource &quot;azurerm_key_vault_secret&quot; &quot;db_password&quot; {
  name         = &quot;db-password&quot;
  value        = var.db_password
  key_vault_id = azurerm_key_vault.main.id

  depends_on = [azurerm_key_vault_access_policy.main]
}

💡 Azure 특징 &amp; 베스트 프랙티스
🎯 Azure 고유 개념

Resource Group: 모든 리소스는 반드시 RG에 속함 (AWS/GCP와 다름)
Location: 리전 이름이 문자열 (예: “Korea Central”, “East US”)
Tags vs Labels: Azure는 “tags” 사용
Naming Convention: 많은 리소스가 전역 고유 이름 필요 (Storage Account 등)

📋 클라우드 비교















































서비스AzureAWSGCPVMVirtual MachinesEC2Compute EngineContainerACI, AKSECS, EKSCloud Run, GKEStorageBlob StorageS3Cloud StorageDatabaseAzure SQLRDSCloud SQLNoSQLCosmos DBDynamoDBFirestoreLoad BalancerApp Gateway, Load BalancerALB, NLBCloud Load Balancing
💡 베스트 프랙티스

리소스 그룹 전략: 환경별, 애플리케이션별로 RG 분리
명명 규칙: &lt;project&gt;-&lt;env&gt;-&lt;resource&gt; (예: myapp-prod-vm)
태그 전략: environment, cost-center, owner 등 일관된 태그
보안: NSG + Service Endpoints + Private Link 조합
비용 관리: Budget Alert 설정, Reserved Instances 활용


📚 참고 자료
🔗 유용한 링크

Azure Provider 공식 문서
Azure 아키텍처 센터
Terraform Azure 모듈



