package main

import (
    &quot;fmt&quot;
    &quot;errors&quot;
)

// 사칙연산 계산기
func calculator(a, b float64, operator string) (float64, error) {
    switch operator {
    case &quot;+&quot;:
        return a + b, nil
    case &quot;-&quot;:
        return a - b, nil
    case &quot;*&quot;:
        return a * b, nil
    case &quot;/&quot;:
        if b == 0 {
            return 0, errors.New(&quot;division by zero&quot;)
        }
        return a / b, nil
    default:
        return 0, fmt.Errorf(&quot;unknown operator: %s&quot;, operator)
    }
}

func calculatorTest() {
    operations := []struct {
        a, b     float64
        operator string
    }{
        {10, 5, &quot;+&quot;},
        {10, 5, &quot;-&quot;},
        {10, 5, &quot;*&quot;},
        {10, 5, &quot;/&quot;},
        {10, 0, &quot;/&quot;},  // 에러 케이스
        {10, 5, &quot;%&quot;},  // 에러 케이스
    }

    for _, op := range operations {
        result, err := calculator(op.a, op.b, op.operator)
        if err != nil {
            fmt.Printf(&quot;%.1f %s %.1f = Error: %v\n&quot;, 
                op.a, op.operator, op.b, err)
        } else {
            fmt.Printf(&quot;%.1f %s %.1f = %.2f\n&quot;, 
                op.a, op.operator, op.b, result)
        }
    }
}
