📦 구조체 정의와 생성



                  구조체란? 



구조체는 서로 다른 타입의 데이터를 하나로 묶는 사용자 정의 타입입니다. Go의 객체지향 프로그래밍의 기초가 됩니다.


package main

import (
    &quot;fmt&quot;
    &quot;time&quot;
)

// 기본 구조체 정의
type Person struct {
    Name    string
    Age     int
    Email   string
    IsActive bool
}

// 구조체 필드에 태그 추가 (JSON, 검증 등에 사용)
type User struct {
    ID       int    `json:&quot;id&quot; validate:&quot;required&quot;`
    Username string `json:&quot;username&quot; validate:&quot;required,min=3&quot;`
    Password string `json:&quot;-&quot;`                    // JSON에서 제외
    Email    string `json:&quot;email&quot; validate:&quot;email&quot;`
    CreatedAt time.Time `json:&quot;created_at&quot;`
}

// 중첩 구조체
type Address struct {
    Street   string
    City     string
    ZipCode  string
    Country  string
}

type Employee struct {
    Person                    // 임베딩 (상속과 유사)
    ID       int             // 직원 ID
    Position string          // 직책
    Salary   float64         // 급여
    Address  Address         // 주소 (컴포지션)
    Manager  *Employee       // 매니저 (자기 참조)
}

func structBasics() {
    // 1. 구조체 생성 방법들

    // 필드별 초기화
    person1 := Person{
        Name:     &quot;Alice&quot;,
        Age:      30,
        Email:    &quot;alice@example.com&quot;,
        IsActive: true,
    }

    // 순서대로 초기화
    person2 := Person{&quot;Bob&quot;, 25, &quot;bob@example.com&quot;, false}

    // 빈 구조체 생성 후 필드 설정
    var person3 Person
    person3.Name = &quot;Charlie&quot;
    person3.Age = 35

    // new()를 사용한 포인터 생성
    person4 := new(Person)
    person4.Name = &quot;Diana&quot;
    person4.Age = 28

    fmt.Printf(&quot;Person1: %+v\n&quot;, person1)
    fmt.Printf(&quot;Person2: %+v\n&quot;, person2)
    fmt.Printf(&quot;Person3: %+v\n&quot;, person3)
    fmt.Printf(&quot;Person4: %+v\n&quot;, *person4)
}
