        FilePath: &quot;/var/log/app.log&quot;,
    }
    fileLogger.Log(&quot;File log message&quot;)        // 오버라이드된 메서드
    fileLogger.Info(&quot;File info message&quot;)      // 임베딩된 메서드가 오버라이드된 Log 호출
}

