import (
    &quot;math/rand&quot;
    &quot;sync&quot;
)

type SafeCounter struct {
    mu    sync.Mutex
    value int
}

func (sc *SafeCounter) Increment() {
    sc.mu.Lock()
    defer sc.mu.Unlock()
    sc.value++
}

func (sc *SafeCounter) GetValue() int {
    sc.mu.Lock()
    defer sc.mu.Unlock()
    return sc.value
}

type SafeMap struct {
    mu   sync.RWMutex
    data map[string]int
}

func NewSafeMap() *SafeMap {
    return &amp;SafeMap{
        data: make(map[string]int),
    }
}

func (sm *SafeMap) Set(key string, value int) {
    sm.mu.Lock()
    defer sm.mu.Unlock()
    sm.data[key] = value
}

func (sm *SafeMap) Get(key string) (int, bool) {
    sm.mu.RLock()  // 읽기 전용 락
    defer sm.mu.RUnlock()
    value, ok := sm.data[key]
    return value, ok
}

func (sm *SafeMap) GetAll() map[string]int {
    sm.mu.RLock()
    defer sm.mu.RUnlock()

    // 복사본 반환
    result := make(map[string]int)
    for k, v := range sm.data {
        result[k] = v
    }
    return result
}

func mutexExample() {
    fmt.Println(&quot;=== Mutex Example ===&quot;)

    counter := &amp;SafeCounter{}
    var wg sync.WaitGroup

    // 10개 고루틴이 동시에 카운터 증가
    for i := 0; i &lt; 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for j := 0; j &lt; 100; j++ {
                counter.Increment()
            }
            fmt.Printf(&quot;Goroutine %d finished\n&quot;, id)
        }(i)
    }

    wg.Wait()
    fmt.Printf(&quot;Final counter value: %d\n&quot;, counter.GetValue())

    fmt.Println(&quot;\n=== RWMutex Example ===&quot;)

    safeMap := NewSafeMap()

    // 데이터 쓰기 고루틴
    wg.Add(1)
    go func() {
        defer wg.Done()
        for i := 0; i &lt; 5; i++ {
            key := fmt.Sprintf(&quot;key%d&quot;, i)
            value := rand.Intn(100)
            safeMap.Set(key, value)
            fmt.Printf(&quot;Set %s = %d\n&quot;, key, value)
            time.Sleep(200 * time.Millisecond)
        }
    }()

    // 데이터 읽기 고루틴들
    for i := 0; i &lt; 3; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for j := 0; j &lt; 10; j++ {
                all := safeMap.GetAll()
                fmt.Printf(&quot;Reader %d: %v\n&quot;, id, all)
                time.Sleep(100 * time.Millisecond)
            }
        }(i)
    }

    wg.Wait()
}
