package middleware

import (
    &quot;log&quot;
    &quot;net/http&quot;
    &quot;time&quot;
)

func LoggingMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()

        // Response writer wrapper to capture status code
        lrw := &amp;loggingResponseWriter{
            ResponseWriter: w,
            statusCode:     200,
        }

        next.ServeHTTP(lrw, r)

        duration := time.Since(start)
        log.Printf(&quot;[%s] %s %s %d %v&quot;, 
            r.Method, r.RequestURI, r.RemoteAddr, lrw.statusCode, duration)
    })
}

type loggingResponseWriter struct {
    http.ResponseWriter
    statusCode int
}

func (lrw *loggingResponseWriter) WriteHeader(code int) {
    lrw.statusCode = code
    lrw.ResponseWriter.WriteHeader(code)
}

// middleware/cors.go
package middleware

func CORSMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set(&quot;Access-Control-Allow-Origin&quot;, &quot;*&quot;)
        w.Header().Set(&quot;Access-Control-Allow-Methods&quot;, &quot;GET, POST, PUT, DELETE, OPTIONS&quot;)
        w.Header().Set(&quot;Access-Control-Allow-Headers&quot;, &quot;Content-Type, Authorization&quot;)

        if r.Method == &quot;OPTIONS&quot; {
            w.WriteHeader(http.StatusOK)
            return
        }

        next.ServeHTTP(w, r)
    })
}

// middleware/ratelimit.go
package middleware

import (
    &quot;net/http&quot;
    &quot;sync&quot;
    &quot;time&quot;

    &quot;golang.org/x/time/rate&quot;
    &quot;github.com/yourusername/todo-api/utils&quot;
)

type IPRateLimiter struct {
    ips map[string]*rate.Limiter
    mu  *sync.RWMutex
    r   rate.Limit
    b   int
}

func NewIPRateLimiter(r rate.Limit, b int) *IPRateLimiter {
    i := &amp;IPRateLimiter{
        ips: make(map[string]*rate.Limiter),
        mu:  &amp;sync.RWMutex{},
        r:   r,
        b:   b,
    }

    return i
}

func (i *IPRateLimiter) AddIP(ip string) *rate.Limiter {
    i.mu.Lock()
    defer i.mu.Unlock()

    limiter := rate.NewLimiter(i.r, i.b)
    i.ips[ip] = limiter

    return limiter
}

func (i *IPRateLimiter) GetLimiter(ip string) *rate.Limiter {
    i.mu.Lock()
    limiter, exists := i.ips[ip]

    if !exists {
        i.mu.Unlock()
        return i.AddIP(ip)
    }

    i.mu.Unlock()
    return limiter
}

var limiter = NewIPRateLimiter(1, 5) // 1 request per second, burst of 5

func RateLimitMiddleware(requestsPerSecond int) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            ip := r.RemoteAddr
            limiter := limiter.GetLimiter(ip)

            if !limiter.Allow() {
                utils.WriteErrorResponse(w, http.StatusTooManyRequests, &quot;RATE_LIMIT_EXCEEDED&quot;, &quot;Too many requests&quot;)
                return
            }

            next.ServeHTTP(w, r)
        })
    }
}

