import asyncio
import aiohttp
from dataclasses import dataclass
from typing import List, Optional

@dataclass
class KeywordData:
    keyword: str
    pc_search_count: int
    mobile_search_count: int
    pc_click_count: float
    mobile_click_count: float
    pc_ctr: float
    mobile_ctr: float
    competition: str
